export function filtrarCids(termo: string): CID[] {
  const t = termo.toUpperCase().replace(/[^A-Z0-9]/g, "");
  const tNorm = termo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  return cidsOnco.filter((c) => {
    const codNorm = c.codigo.replace(".", "");
    const descNorm = c.descricao.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return codNorm.includes(t) || descNorm.includes(tNorm);
  }).slice(0, 20);
}

