export function cidsPorCapitulo(prefixos: string[]): CID[] {
  return cidsOnco.filter((c) => prefixos.some((p) => c.codigo.startsWith(p)));
}

export function buscarCidExato(codigo: string): CID | undefined {
  const norm = codigo.toUpperCase().replace(/[^A-Z0-9]/g, "");
  return cidsOnco.find((c) => c.codigo.toUpperCase().replace(/[^A-Z0-9]/g, "") === norm);
}

