export function buscarProcedimentos(cidBusca: string, indicacao?: string): Procedimento[] {
  const cidNorm = cidBusca.toUpperCase().replace(/[^A-Z0-9]/g, "");
  return procedimentos.filter((p) => {
    const matchSubgrupo = !indicacao || p.subgrupo === indicacao;
    const matchCid = p.cidsCompativeis.some((c) => {
      const cNorm = c.toUpperCase().replace(/[^A-Z0-9]/g, "");
      return cNorm === cidNorm || cidNorm.startsWith(cNorm) || cNorm.startsWith(cidNorm);
    });
    return matchSubgrupo && matchCid;
  });
}

export function indicacoesCompativeis(cidBusca: string): string[] {
  if (!cidBusca) return [];
  const cidNorm = cidBusca.toUpperCase().replace(/[^A-Z0-9]/g, "");
  const subgrupos = new Set<string>();
  for (const p of procedimentos) {
    const matchCid = p.cidsCompativeis.some((c) => {
      const cNorm = c.toUpperCase().replace(/[^A-Z0-9]/g, "");
      return cNorm === cidNorm || cidNorm.startsWith(cNorm) || cNorm.startsWith(cidNorm);
    });
    if (matchCid) subgrupos.add(p.subgrupo);
  }
  return Array.from(subgrupos);
}

export function buscarPorCodigo(codigo: string): Procedimento | undefined {
  const norm = codigo.replace(/[^0-9]/g, "").replace(/^0+/, "");
  return procedimentos.find((p) => p.codigo === norm);
}

export function listarProcedimentos(): Procedimento[] {
  return procedimentos;
}

export function filtrarProcedimentos(texto: string): Procedimento[] {
  const textoLower = texto.toLowerCase();
  const numOnly = texto.replace(/[^0-9]/g, "").replace(/^0+/, "");
  if (texto.length < 2) return [];
  return procedimentos.filter((p) =>
    (numOnly.length >= 2 && (p.codigo.includes(numOnly) || p.codigo.startsWith(numOnly))) ||
    p.nome.toLowerCase().includes(textoLower)
  ).slice(0, 20);
}